"""Generate Java/browser domain constants from the ONE existing offer contract."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
c=json.loads((ROOT/'app/src/main/assets/offer-contract.json').read_text())
wire=json.dumps(c,ensure_ascii=False,separators=(',',':'))
java='''package at.hausgarten.service;
import org.json.*;
/** GENERATED by tools/sync_offer_contract.py; edit offer-contract.json only. */
final class OfferContract {
 static JSONObject data()throws Exception{return new JSONObject(%s);}
 static String[] values(String key){try{JSONArray a=data().getJSONArray(key);String[] out=new String[a.length()];for(int i=0;i<a.length();i++)out[i]=a.getString(i);return out;}catch(Exception e){throw new IllegalStateException("Dokumentvertrag fehlt.");}}
 static JSONObject type(String id){try{JSONArray a=data().getJSONArray("document_types");for(int i=0;i<a.length();i++)if(id.equals(a.getJSONObject(i).getString("id")))return a.getJSONObject(i);return new JSONObject();}catch(Exception e){throw new IllegalStateException(e);}}
 static String[] types(){try{JSONArray a=data().getJSONArray("document_types");String[] out=new String[a.length()];for(int i=0;i<a.length();i++)out[i]=a.getJSONObject(i).getString("id");return out;}catch(Exception e){throw new IllegalStateException(e);}}
 private OfferContract(){}
}
'''%json.dumps(wire,ensure_ascii=False)
outputs={ROOT/'app/src/main/java/at/hausgarten/service/OfferContract.java':java,ROOT/'app/src/main/assets/offer-contract.js':'/* Generated from offer-contract.json. */\nwindow.OfferContract=Object.freeze('+wire+');\n'}
for p,text in outputs.items():
 if '--write' in sys.argv:p.write_text(text)
 elif not p.exists() or p.read_text()!=text:raise SystemExit('Stale generated offer contract: '+str(p.relative_to(ROOT)))
print('PASS shared offer contract Java/browser parity')
